style.css:
/* Pink PDF — Chrome */
 /* i really want this to be global */

/* pink color palette */
:root {
  --my-pink-bg: #fce7f3;
  --my-pink-toolbar: #f9a8d4;
  --my-pink-paper: #fff7fb;
  --my-pink-text: #713b57;
  --my-pink-accent: #db2777;
}

/* pink background */
html,
body {
  background: var(--my-pink-bg) !important;
  color: var(--my-pink-text) !important;
}

/* pink toolbar */
#toolbarContainer,
#toolbarViewer {
  background: var(--my-pink-toolbar) !important;
}

/* pink PDF pages */
.pdfViewer .page {
  background: var(--my-pink-paper) !important;
  border-color: #f3c4dc !important;
  box-shadow: 0 3px 14px #d98ab555 !important;
}

/* pink links */
.pdfViewer a {
  color: var(--my-pink-accent) !important;
}

/* pink highlights */
.pdfViewer .highlight {
  background: #f9a8d466 !important;
}
